def store_data(cmd_arg, file_ptr, blk_size=8192):
            # like storbinary() except it sends "type a" instead of
            # "type i" before starting the transfer
            self.ftp_client.voidcmd('type a')
            connection = self.ftp_client.transfercmd(cmd_arg)
            connection.settimeout(TIMEOUT)
            while 1:
                buffer_data = file_ptr.read(blk_size)
                if not buffer_data:
                    break
                connection.sendall(buffer_data)
            connection.close()
            return self.ftp_client.voidresp()

