def ClusterSubstitute(cmdInput, srvHost, runUser, nodeIdx=0, usrParams=None):
    # Construct substitution dictionary
    subsMap = {'host' : srvHost, 'user' : runUser, 'node' : nodeIdx}
    if (usrParams != None):
        for key,value in usrParams.items():
            subsMap[key] = value[nodeIdx-1]

    # Perform substition. We do this twice because some usrParams items might have host, user and node in them
    if (isinstance(cmdInput, str)):
        return (cmdInput % subsMap) % subsMap
    elif (isinstance(cmdInput, list)):
        return [((x % subsMap) % subsMap) for x in cmdInput]
    return None

